<body>

    <h1>Snake</h1>

    <div id="game-container">
        <!-- The Game Canvas -->
        <canvas id="snake" width="400" height="400"></canvas>

        <!-- Controls & Score -->
        <div style="display: flex; flex-direction: column; gap: 15px;">
            <div id="score">Score: 0</div>

            <div class="controls">
                <button id="start" class="primary">START</button>
                <button id="pause">PAUSE</button>
                <button id="reset" class="danger">RESET</button>
            </div>
        </div>
    </div>

<script>
/**
 * Snake Game Implementation
 */

// --- Configuration ---
const TILE_SIZE = 20; // Number of pixels per tile
const BOARD_WIDTH_CELLS = 20;
const BOARD_HEIGHT_CELLS = 20; // >= 10 required
const TICK_RATE_MS = 150; // Speed of the game (lower is faster)

// --- DOM Elements ---
const canvas = document.getElementById('snake');
const scoreEl = document.getElementById('score');
const startBtn = document.getElementById('start');
const pauseBtn = document.getElementById('pause');
const resetBtn = document.getElementById('reset');

// --- Game State ---
let snake = [];
let food = null;
let dir = 'right'; // Current movement direction
let nextDir = 'right'; // Buffered input direction
let score = 0;
let lastRenderTime = 0;
let isRunning = false;
let isPaused = false;
let gameOver = false;

// --- The API (window.game) ---
const game = {
    w: BOARD_WIDTH_CELLS,
    h: BOARD_HEIGHT_CELLS,

    reset() {
        stopGame(); // Stop loop if running
        snake = [
            { x: 10, y: 10 },
            { x: 10, y: 11 },
            { x: 10, y: 12 }
        ]; // Start length >= 3
        dir = 'up';
        nextDir = 'up';
        score = 0;
        gameOver = false;
        isRunning = true;
        isPaused = false;
        spawnFood();

        // Draw initial state immediately
        requestAnimationFrame(loop);

        startBtn.innerText = "RUNNING";
        startBtn.disabled = true;
    },

    setDir(direction) {
        if (gameOver || !isRunning) return;

        const currentMove = this.getMoveVector(dir);
        const candidateMove = this.getMoveVector(direction);

        // Prevent 180 reversal
        if (currentMove.x === -candidateMove.x && currentMove.y === -candidateMove.y) {
            return; // Ignore reversal
        }

        nextDir = direction;
    },

    tick() {
        if (!isRunning || isPaused || gameOver) return;

        const head = snake[0];

        // Calculate new position based on input (nextDir) and current heading? 
        // Actually, standard snake: head moves in dir. User inputs next turn direction.
        // The movement happens based on the direction *at the moment of the tick*.
        // But input is queued. So we check nextDir to determine velocity.

        const move = this.getMoveVector(nextDir);

        let newHead = { x: head.x + move.x, y: head.y + move.y };

        // Check Wall Collision
        if (newHead.x < 0 || newHead.x >= game.w || newHead.y < 0 || newHead.y >= game.h) {
            endGame();
            return;
        }

        // Check Body Collision
        // Don't check the tail tip because it will move forward in this tick unless we eat.
        for (let i = 0; i < snake.length - 1; i++) {
            if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
                endGame();
                return;
            }
        }

        // Move Snake
        snake.unshift(newHead); // Add new head

        // Check Food
        if (newHead.x === food.x && newHead.y === food.y) {
            score += 10;
            scoreEl.innerText = "Score: " + score;
            spawnFood();
            // Don't pop tail, so snake grows
        } else {
            snake.pop(); // Remove tail
        }

        this.draw();
    },

    setFood(x, y) {
        food = { x, y };
        this.draw();
    },

    snake() { return snake; },
    food() { return food; },
    alive() { 
        // Alive is technically !gameOver, but checking active state might be better.
        // Prompt implies boolean status.
        return !gameOver;
    },
    score() { return score; }
};

// --- Helper Functions ---

function stopGame() {
    clearTimeout(gameLoopId); // If using setTimeout logic inside loop
    isRunning = false;
}

function getMoveVector(direction) {
    switch(direction) {
        case 'up': return { x: 0, y: -1 };
        case 'down': return { x: 0, y: 1 };
        case 'left': return { x: -1, y: 0 };
        case 'right': return { x: 1, y: 0 };
    }
    return { x: 0, y: 0 };
}

function spawnFood() {
    let freeCell = true;
    while (freeCell) {
        const fX = Math.floor(Math.random() * game.w);
        const fY = Math.floor(Math.random() * game.h);

        // Check if this spot is occupied by snake
        let occupied = false;
        for(let part of snake) {
            if(part.x === fX && part.y === fY) occupied = true;
        }

        if (!occupied) {
            food = { x: fX, y: fY };
            freeCell = false;
        }
    }
}

function endGame() {
    gameOver = true;
    isRunning = false;
    drawOverlay("GAME OVER");
    // Stop the loop manually if using RAF logic
    gameLoopId = null; 
    lastRenderTime = 0;
}

// --- Rendering Logic ---

const ctx = canvas.getContext('2d');

function resizeCanvas() {
    canvas.width = BOARD_WIDTH_CELLS * TILE_SIZE;
    canvas.height = BOARD_HEIGHT_CELLS * TILE_SIZE;
}

function drawOverlay(text) {
    if (!text) return;

    // Simple overlay logic for game over/pause state handled by internal flags
    // but for the "Graded API" requirement we rely on flags. 
    // For visual feedback, let's use simple text drawing on canvas if needed? 
    // Or UI overlay div. Let's stick to canvas draw function being called constantly.
}

function draw() {
    // Clear background
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Grid (Optional visual polish)
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 1;
    for(let x=0; x<=game.w; x++) {
        ctx.beginPath(); ctx.moveTo(x*TILE_SIZE, 0); ctx.lineTo(x*TILE_SIZE, canvas.height); ctx.stroke();
    }
    for(let y=0; y<=game.h; y++) {
        ctx.beginPath(); ctx.moveTo(0, y*TILE_SIZE); ctx.lineTo(canvas.width, y*TILE_SIZE); ctx.stroke();
    }

    // Draw Food
    if (food) {
        ctx.fillStyle = '#ff5252'; // Red/Orange
        // Round food slightly
        const fx = food.x * TILE_SIZE + 4;
        const fy = food.y * TILE_SIZE + 4;
        const fsz = TILE_SIZE - 8;
        ctx.beginPath();
        ctx.arc(fx, fy, fsz/2, 0, Math.PI*2);
        ctx.fill();

        // Little shine
        ctx.fillStyle = 'rgba(255,255,255,0.4)';
        ctx.beginPath();
        ctx.arc(fx-2, fy-2, fsz/6, 0, Math.PI*2);
        ctx.fill();
    }

    // Draw Snake
    for (let i = snake.length - 1; i >= 0; i--) {
        const part = snake[i];
        const px = part.x * TILE_SIZE + 1;
        const py = part.y * TILE_SIZE + 1;
        const size = TILE_SIZE - 2; // Slight gap between segments

        ctx.fillStyle = (i === 0) ? '#4CAF50' : '#388E3C'; // Head is brighter green

        // Draw rounded rect for head, or simple rects. Rects are easier and standard for Snake.
        ctx.fillRect(px, py, size, size);

        // Draw Eyes on Head
        if (i === 0) {
            ctx.fillStyle = 'white';
            const cx = px + size/2;
            const cy = py + size/2;
            // Simple logic to place eyes based on direction would be complex 
            // but a simple white center dot or offset is enough.
            // Let's just do simple eyes relative to head orientation
            ctx.beginPath(); ctx.arc(cx - 4, cy - 4, 3, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(cx + 4, cy - 4, 3, 0, Math.PI*2); ctx.fill();
        }
    }
}

function drawOverlayText(text) {
    ctx.fillStyle = 'rgba(0,0,0,0.8)';
    ctx.fillRect(0,0,canvas.width, canvas.height);

    ctx.fillStyle = 'white';
    ctx.font = "bold 40px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(text, canvas.width/2, canvas.height/2);
}

function loop(currentTime) {
    if (!gameLoopId) gameLoopId = requestAnimationFrame(loop);

    // Pause logic handled by checking isPaused inside the draw/update flow? 
    // Or separate timer. Simplest: Check isRunning flag.

    // Wait for correct interval
    const secondsSinceLastRender = (currentTime - lastRenderTime) / 1000;
    if (secondsSinceLastRender < TICK_RATE_MS / 1000) return;

    game.tick();
    lastRenderTime = currentTime;
}

// --- Event Listeners ---

window.addEventListener('keydown', (e) => {
    // Prevent scrolling with arrow keys
    if(["ArrowUp","ArrowDown","ArrowLeft","ArrowRight"].indexOf(e.code) > -1) {
        e.preventDefault();
    }

    switch (e.key) {
        case 'ArrowUp': game.setDir('up'); break;
        case 'ArrowDown': game.setDir('down'); break;
        case 'ArrowLeft': game.setDir('left'); break;
        case 'ArrowRight': game.setDir('right'); break;
    }
});

startBtn.addEventListener('click', () => {
    if (!isRunning && !gameOver) {
        // If it was a reset state but user hit pause (conceptually), we'd need logic.
        // But here buttons are specific.
        // "START" usually implies starting a fresh game or continuing. 
        // Based on API: reset() starts the loop.
        if (gameOver) {
            game.reset();
        } else if (!isRunning) {
             // Maybe this button toggles start from paused? 
             // Let's make it "Play". If paused, resume. If stopped, start.
             isRunning = true; isPaused = false;
             // Loop resumes immediately because lastRenderTime will be old
        }
    }
});

pauseBtn.addEventListener('click', () => {
    if (isRunning && !gameOver) {
        isPaused = true;
        pauseBtn.innerText = "RESUME";
        drawOverlayText("PAUSED"); // Visual cue
    } else if (!isRunning && !gameOver) {
        // Start button handles start usually, but let's toggle resume logic here
        // to cover edge cases.
        isPaused = false; 
        lastRenderTime = 0; // Force immediate next update? No, tick logic handles delta time.
    } else if (gameOver) {
         // Do nothing on pause if game over
    }
});

resetBtn.addEventListener('click', () => {
    stopGame();
    isPaused = false;
    game.reset();
});

// Initialize dimensions immediately
resizeCanvas();

</script>
</body>
</html>
